SELECT * FROM app.bootstrap_first_owner('00000000-0000-0000-0000-000000009801','owner.98@example.test','Owner Ninety Eight',decode('9898989898989898989898989898989898989898989898989898989898989898','hex'),'req-98','corr-98');
SELECT set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000009801',true);
