VALUES ('Reconciliation Contractor','Reconciliation Contractor','USD','Asia/Singapore',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000009801'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000009801'));
SELECT * FROM public.server_create_client_record('00000000-0000-0000-0000-000000009801','Reconciliation Client',NULL,'reconciliation.client@example.test');


SELECT set_config('app.document_metadata_context','owner_metadata_mutation',true);
SELECT set_config('app.document_metadata_context','',true);

VALUES ('30000000-0000-4000-8000-000000009808','41000000-0000-4000-8000-000000009801','temporary/30000000-0000-4000-8000-000000009808/HHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHHH','finalized-temp.pdf','application/pdf','application/pdf',10,decode('cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd','hex'),'GENERAL',false,(SELECT id FROM app.clients WHERE display_name='Reconciliation Client'),(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000009801'),now()+interval '5 minutes','FINALIZED',now(),now(),now(),now(),now(),now(),now(),'objects/41000000-0000-4000-8000-000000009801/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','41000000-0000-4000-8000-000000009801');

SELECT set_config('app.document_lifecycle_context','owner_document_lifecycle_mutation',true);
VALUES ('41000000-0000-4000-8000-000000009804','41000000-0000-4000-8000-000000009805',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000009801'));
VALUES ('41000000-0000-4000-8000-000000009806','RESTORED_PRIVATE',(SELECT id FROM app.users WHERE auth_subject='00000000-0000-0000-0000-000000009801'));
SELECT set_config('app.document_lifecycle_context','',true);



CREATE TEMP TABLE reconciliation_before AS SELECT * FROM public.server_storage_reconciliation_report();

SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009801' $$, $$ VALUES ('OK'::text,'NONE'::text) $$, 'healthy active reservation with expected object is OK');
SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009802' $$, $$ VALUES ('INVALIDATION_CANDIDATE'::text,'INVALIDATE_RESERVATION'::text) $$, 'expired reservation with object is invalidation candidate');
SELECT results_eq($$ SELECT classification::text, detail_code FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009803' $$, $$ VALUES ('MISSING_OBJECT'::text,'reservation_object_missing'::text) $$, 'reservation with missing temporary object is reported');
SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009804' $$, $$ VALUES ('INVALIDATION_CANDIDATE'::text,'INVALIDATE_RESERVATION'::text) $$, 'failed reservation with object is invalidation candidate');
SELECT results_eq($$ SELECT classification::text, detail_code FROM reconciliation_before WHERE storage_object_key LIKE 'temporary/99999999%' $$, $$ VALUES ('ORPHAN_TEMPORARY_CANDIDATE'::text,'temporary_object_without_valid_reservation'::text) $$, 'orphan temporary object is reported without deletion');
SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009808' $$, $$ VALUES ('REVIEW'::text,'POLICY_DECISION_REQUIRED'::text) $$, 'finalized upload with leftover temporary object requires policy review');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009805' $$, $$ VALUES ('QUARANTINED'::text) $$, 'quarantined upload reported but retained');
SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009806' $$, $$ VALUES ('PROCESSING_INCOMPLETE'::text,'RETRY_EXISTING_WORKFLOW'::text) $$, 'SCAN_FAILED reported without automatic retry');
SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE upload_id='30000000-0000-4000-8000-000000009807' $$, $$ VALUES ('PROCESSING_INCOMPLETE'::text,'MANUAL_REVIEW'::text) $$, 'SCAN_IN_PROGRESS reported without stale timeout');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE document_id='41000000-0000-4000-8000-000000009801' AND finding_source='finalized_document' $$, $$ VALUES ('OK'::text) $$, 'finalized document with object is OK');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE document_id='41000000-0000-4000-8000-000000009802' AND finding_source='finalized_document' $$, $$ VALUES ('MISSING_OBJECT'::text) $$, 'finalized DB record with missing object is reported');
SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE storage_object_key LIKE 'objects/99999999%' $$, $$ VALUES ('UNEXPECTED_OBJECT'::text,'POLICY_DECISION_REQUIRED'::text) $$, 'unexpected final object is review only');
SELECT results_eq($$ SELECT count(*)::integer, min(classification::text), min(recommended_action::text) FROM reconciliation_before WHERE storage_object_key='objects/not-a-uuid/file' $$, $$ VALUES (1, 'UNEXPECTED_OBJECT'::text, 'POLICY_DECISION_REQUIRED'::text) $$, 'malformed final object key is reported once without throwing');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE document_id='41000000-0000-4000-8000-000000009803' AND finding_source='finalized_document' $$, $$ VALUES ('OK'::text) $$, 'archived finalized object retained as OK');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE document_id='41000000-0000-4000-8000-000000009804' AND finding_source='finalized_document' $$, $$ VALUES ('OK'::text) $$, 'superseded finalized object retained as OK');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE document_id='41000000-0000-4000-8000-000000009806' AND finding_source='finalized_document' $$, $$ VALUES ('OK'::text) $$, 'restored-private finalized object retained as OK');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE derivative_document_id='41000000-0000-4000-8000-000000009807' $$, $$ VALUES ('OK'::text) $$, 'READY derivatives with both objects are OK');
SELECT results_eq($$ SELECT classification::text, detail_code FROM reconciliation_before WHERE derivative_document_id='41000000-0000-4000-8000-000000009808' $$, $$ VALUES ('MISSING_OBJECT'::text,'ready_derivative_preview_missing'::text) $$, 'READY derivative missing object is reported');
SELECT results_eq($$ SELECT classification::text, recommended_action::text FROM reconciliation_before WHERE derivative_document_id='41000000-0000-4000-8000-000000009809' $$, $$ VALUES ('PROCESSING_INCOMPLETE'::text,'RETRY_EXISTING_WORKFLOW'::text) $$, 'photograph FAILED reported without automatic retry');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE derivative_document_id='41000000-0000-4000-8000-000000009810' $$, $$ VALUES ('PROCESSING_INCOMPLETE'::text) $$, 'PENDING derivative state is incomplete without stale timeout');
SELECT results_eq($$ SELECT classification::text FROM reconciliation_before WHERE derivative_document_id='41000000-0000-4000-8000-000000009811' $$, $$ VALUES ('DERIVATIVE_MISMATCH'::text) $$, 'derivative metadata/object mismatch is reported');
SELECT results_eq($$ SELECT classification::text, detail_code FROM reconciliation_before WHERE storage_object_key LIKE 'derivatives/99999999%' $$, $$ VALUES ('UNEXPECTED_OBJECT'::text,'derivative_object_without_expected_record'::text) $$, 'unmatched derivative object is reported');

CREATE TEMP TABLE reconciliation_after AS SELECT * FROM public.server_storage_reconciliation_report();
SELECT results_eq($$ SELECT finding_source, classification::text, recommended_action::text, storage_object_key, upload_id, document_id, derivative_document_id, status, detail_code FROM reconciliation_after $$, $$ SELECT finding_source, classification::text, recommended_action::text, storage_object_key, upload_id, document_id, derivative_document_id, status, detail_code FROM reconciliation_before $$, 'repeated reconciliation returns equivalent findings');
SELECT is((SELECT count(*)::integer FROM app.document_uploads), 8, 'reconciliation does not mutate upload lifecycle rows');
SELECT is((SELECT count(*)::integer FROM app.documents), 11, 'reconciliation does not delete or create document records');
SELECT is((SELECT count(*)::integer FROM storage.objects WHERE bucket_id='documents-private'), 26, 'reconciliation does not physically delete storage objects');
SELECT is((SELECT count(*)::integer FROM app.document_replacements), 1, 'reconciliation preserves replacement history');
SELECT is((SELECT count(*)::integer FROM app.document_client_access_privacy), 1, 'reconciliation preserves restored-private lifecycle marker');
SELECT is((SELECT count(*)::integer FROM app.activity_logs WHERE action ILIKE '%reconciliation%'), 0, 'reconciliation creates no business activity logs');
SELECT ok(NOT EXISTS (SELECT 1 FROM reconciliation_before WHERE recommended_action::text='DELETE'), 'report never returns DELETE action');
SELECT ok(EXISTS (SELECT 1 FROM reconciliation_before WHERE detail_code='finalized_upload_temporary_object_present') AND NOT EXISTS (SELECT 1 FROM reconciliation_before WHERE storage_object_key LIKE 'objects/41000000-0000-4000-8000-000000009801%' AND classification::text IN ('ORPHAN_TEMPORARY_CANDIDATE','INVALIDATION_CANDIDATE')), 'finalized object is not disposable merely because old reservation exists');
SELECT ok((SELECT count(*) FROM app.document_scans)=0, 'reconciliation does not create scan history or retry scanner failures');

SELECT * FROM finish();
